static size_t checked = 0;
static void require(bool value, const char* message) {
    if (!value) throw std::runtime_error(message);
}
static bool equal(float a, float b) {
    return (std::isnan(a) && std::isnan(b)) || std::memcmp(&a, &b, sizeof(a)) == 0;
}
struct Pack {
    std::vector<int> values;
    std::vector<float> scales;
    bool valid = true;
    explicit Pack(const std::vector<float>& x, size_t width) : values(width), scales(width / 32) {
        for (size_t b = 0; b < scales.size(); ++b) {
            float maximum = 0;
            for (size_t j = 0; j < 32; ++j) {
                if (!std::isfinite(x[b * 32 + j])) { valid = false; return; }
                maximum = std::max(maximum, std::fabs(x[b * 32 + j]));
            }
            scales[b] = maximum / 32767.0f;
            if (maximum != 0 && scales[b] == 0) { valid = false; return; }
            const float inverse = scales[b] > 0 ? 1.0f / scales[b] : 0;
            if (!std::isfinite(inverse)) { valid = false; return; }
            for (size_t j = 0; j < 32; ++j) {
                const float rounded = std::nearbyint(x[b * 32 + j] * inverse);
                values[b * 32 + j] = std::max(-32768, std::min(32767, int(rounded)));
            }
        }
    }
};
static bool scalar_dot(const uint8_t* row, const Pack& p, float& result) {
    if (!p.valid) return false;
    float lanes[8]{};
    for (size_t b = 0; b < p.scales.size(); ++b) {
        const uint8_t* w = row + b * 34;
        const uint16_t half = uint16_t(w[0] | uint16_t(w[1]) << 8);
        const float weight = f16_to_f32(half);
        const float scale = weight * p.scales[b];
        if (!std::isfinite(scale) || (scale == 0 && weight != 0 && p.scales[b] != 0)) return false;
        for (size_t lane = 0; lane < 8; ++lane) {
            int64_t sum = 0;
            for (size_t t = 0; t < 4; ++t) {
                const size_t j = 2 * lane + (t & 1) + (t / 2) * 16;
                const int signed_weight = w[2 + j] < 128 ? int(w[2 + j]) : int(w[2 + j]) - 256;
                sum += int64_t(signed_weight) * p.values[b * 32 + j];
            }
            require(std::abs(sum) <= 16777216, "integer product bound");
            lanes[lane] = std::fma(float(sum), scale, lanes[lane]);
        }
    }
    const float a = lanes[0] + lanes[4], b = lanes[1] + lanes[5];
    const float c = lanes[2] + lanes[6], d = lanes[3] + lanes[7];
    result = (a + b) + (c + d);
    return std::isfinite(result);
}
struct Matrix {
    uint32_t type;
    size_t rows, width;
    std::vector<uint8_t> bytes;
    std::vector<float> weights, group, separate, control;
    Matrix(uint32_t t, size_t r, size_t n, size_t batch, uint16_t scale)
        : type(t), rows(r), width(n), group(r * batch + 2, 123456),
          separate(group), control(group) {
        if (type == gguf::GGML_TYPE_F32) {
            weights.resize(rows * width);
            for (size_t i = 0; i < weights.size(); ++i) weights[i] = float(int((i * 37 + 13) % 257) - 128) / 128;
        } else if (type == gguf::GGML_TYPE_Q8_0) {
            bytes.resize(rows * (width / 32) * 34);
            for (size_t b = 0; b < bytes.size() / 34; ++b) {
                bytes[b * 34] = uint8_t(scale); bytes[b * 34 + 1] = uint8_t(scale >> 8);
                for (size_t j = 0; j < 32; ++j) bytes[b * 34 + 2 + j] = uint8_t(b * 13 + j * 19);
            }
        } else {
            require(width % 256 == 0, "Q4 width");
            bytes.resize(rows * (width / 256) * gguf::Q4_K_TYPESIZE);
            for (size_t i = 0; i < bytes.size(); ++i) bytes[i] = uint8_t(i * 73 + 19);
            for (size_t b = 0; b < bytes.size(); b += gguf::Q4_K_TYPESIZE) {
                bytes[b] = 0; bytes[b + 1] = 0x20; bytes[b + 2] = 0; bytes[b + 3] = 0x20;
            }
        }
    }
    const uint8_t* data() const { return type == gguf::GGML_TYPE_F32 ? reinterpret_cast<const uint8_t*>(weights.data()) : bytes.data(); }
    backend::Projection projection(std::vector<float>& target) { return {type, data(), target.data() + 1, rows}; }
};
static void case_group(backend::CpuBackend& cpu, control_backend::CpuBackend& control,
    size_t width, size_t batch, int threads, bool mixed, size_t r0, size_t r1, size_t r2,
    const std::vector<float>& x, uint16_t scale) {
    cpu.set_threads(threads); control.set_threads(threads);
    Matrix a(gguf::GGML_TYPE_Q8_0, r0, width, batch, scale);
    Matrix b(mixed ? gguf::GGML_TYPE_F32 : gguf::GGML_TYPE_Q8_0, r1, width, batch, scale);
    Matrix c(mixed ? gguf::GGML_TYPE_Q4_K : gguf::GGML_TYPE_Q8_0, r2, width, batch, scale);
    Pack pack(x, width);
    cpu.matmul_group({a.projection(a.group), b.projection(b.group), c.projection(c.group)}, x.data(), width, batch);
    control.matmul_group({a.projection(a.control), b.projection(b.control), c.projection(c.control)}, x.data(), width, batch);
    for (Matrix* m : {&a, &b, &c}) {
        cpu.matmul(m->type, m->data(), x.data(), m->separate.data() + 1, width, m->rows, batch);
        require(m->group.front() == 123456 && m->group.back() == 123456, "group output boundary");
        require(m->separate.front() == 123456 && m->separate.back() == 123456, "separate output boundary");
        for (size_t i = 0; i < m->rows * batch; ++i) {
            float expected = m->control[i + 1];
            if (batch == 1 && m->type == gguf::GGML_TYPE_Q8_0) {
                float scalar = 0;
                if (scalar_dot(m->data() + i * (width / 32) * 34, pack, scalar)) expected = scalar;
                require(equal(m->group[i + 1], m->separate[i + 1]), "Q8 group/separate mismatch");
            }
            if (!equal(m->group[i + 1], expected)) {
                std::cerr << "width=" << width << " batch=" << batch << " threads=" << threads
                    << " mixed=" << mixed << " type=" << m->type << " row=" << i << " scale=" << scale << '\n';
                throw std::runtime_error("oracle/control mismatch");
            }
            ++checked;
        }
    }
    // Inspect packing only after dispatch/output checks; never pre-seed that call.
    if (batch == 1) {
        require(cpu.pack_q16_activation(x.data(), width / 32) == pack.valid, "pack acceptance");
        if (pack.valid) {
            for (size_t i = 0; i < width; ++i) require(cpu.q16_values_[i] == pack.values[i], "packed integer");
            for (size_t i = 0; i < width / 32; ++i) require(equal(cpu.q16_scales_[i], pack.scales[i]), "packed scale");
        }
    }
}
static void unseeded_reuse(backend::CpuBackend& cpu, control_backend::CpuBackend& control) {
    const size_t width = 256;
    cpu.set_threads(6); control.set_threads(6);
    Matrix a(gguf::GGML_TYPE_Q8_0, 49, width, 1, 0x3c00);
    Matrix b(gguf::GGML_TYPE_Q8_0, 64, width, 1, 0x3c00);
    Matrix c(gguf::GGML_TYPE_Q8_0, 65, width, 1, 0x3c00);
    for (bool grouped : {true, false}) {
        // No direct packing call occurs anywhere in either four-input sequence.
        for (int stage = 0; stage < 4; ++stage) {
            std::vector<float> x(width);
            for (size_t i = 0; i < width; ++i)
                x[i] = float(int((i * size_t(43 + stage * 12) + size_t(stage * 19 + 7)) % 271) - 135)
                    / float(17 + stage * 3);
            if (stage == 2) x.back() = std::numeric_limits<float>::quiet_NaN();
            Pack expected_pack(x, width);
            require(expected_pack.valid == (stage != 2), "reuse fixture packing state");
            for (Matrix* m : {&a, &b, &c}) std::fill(m->group.begin(), m->group.end(), 123456);
            if (grouped) {
                cpu.matmul_group({a.projection(a.group), b.projection(b.group), c.projection(c.group)}, x.data(), width, 1);
            } else {
                for (Matrix* m : {&a, &b, &c})
                    cpu.matmul(m->type, m->data(), x.data(), m->group.data() + 1, width, m->rows, 1);
            }
            control.matmul_group({a.projection(a.control), b.projection(b.control), c.projection(c.control)}, x.data(), width, 1);
            for (Matrix* m : {&a, &b, &c}) {
                require(m->group.front() == 123456 && m->group.back() == 123456, "reuse output boundary");
                for (size_t row = 0; row < m->rows; ++row) {
                    float expected = m->control[row + 1];
                    if (expected_pack.valid)
                        require(scalar_dot(m->data() + row * (width / 32) * 34, expected_pack, expected), "reuse scalar path");
                    if (!equal(m->group[row + 1], expected)) {
                        std::cerr << "unseeded grouped=" << grouped << " stage=" << stage << " row=" << row << '\n';
                        throw std::runtime_error("unseeded reuse oracle/control mismatch");
                    }
                    ++checked;
                }
            }
        }
    }
}
static void finite_half_sweep(backend::CpuBackend& cpu) {
    const size_t rows = 63488;
    Matrix all(gguf::GGML_TYPE_Q8_0, rows, 32, 1, 0);
    Matrix tail(gguf::GGML_TYPE_Q8_0, 49, 32, 1, 0x3c00);
    cpu.set_threads(6);
    alignas(32) float storage[33]{};
    float* const input = storage + 1;
    for (int weight : {-128, 127}) {
        size_t row = 0;
        for (unsigned half = 0; half < 65536; ++half) {
            if ((half & 0x7c00) == 0x7c00) continue;
            uint8_t* block = all.bytes.data() + row++ * 34;
            block[0] = uint8_t(half); block[1] = uint8_t(half >> 8);
            std::fill(block + 2, block + 34, uint8_t(weight));
        }
        require(row == rows, "finite half sweep extent");
        for (size_t lane : {size_t(7), size_t(24)}) {
            for (float sign : {-1.0f, 1.0f}) {
                std::fill(input, input + 32, 0.0f);
                input[lane] = sign;
                Pack expected_pack(std::vector<float>(input, input + 32), 32);
                cpu.matmul_group({all.projection(all.group), tail.projection(tail.group)}, input, 32, 1);
                cpu.matmul(all.type, all.data(), input, all.separate.data() + 1, 32, rows, 1);
                for (Matrix* m : {&all, &tail}) {
                    require(m->group.front() == 123456 && m->group.back() == 123456, "half sweep output boundary");
                    for (size_t r = 0; r < m->rows; ++r) {
                        float expected = 0;
                        require(scalar_dot(m->data() + r * 34, expected_pack, expected), "finite half scalar path");
                        require(equal(m->group[r + 1], expected), "finite half grouped product");
                        if (m == &all) require(equal(m->separate[r + 1], expected), "finite half standalone product");
                        ++checked;
                    }
                }
                require(all.separate.front() == 123456 && all.separate.back() == 123456, "half sweep separate boundary");
            }
        }
    }
}
#ifdef Q16_WITNESS
static void witness_dispatch(backend::CpuBackend& cpu) {
    using namespace backend::q16_witness;
    const size_t width = 256;
    cpu.set_threads(6);
    std::vector<float> x(width, 1.0f);
    Matrix a(gguf::GGML_TYPE_Q8_0, 49, width, 1, 0x3c00);
    Matrix b(gguf::GGML_TYPE_Q8_0, 64, width, 1, 0x3c00);
    Matrix c(gguf::GGML_TYPE_Q8_0, 65, width, 1, 0x3c00);
    reset();
    cpu.matmul_group({a.projection(a.group), b.projection(b.group), c.projection(c.group)}, x.data(), width, 1);
    require(get(group_packs) == 1 && get(standalone_packs) == 0, "one shared pack witness");
    require(get(group_integer_rows) == 178 && get(group_float_rows) == 0, "group rows witness");
    reset();
    for (Matrix* m : {&a, &b, &c}) cpu.matmul(m->type, m->data(), x.data(), m->separate.data() + 1, width, m->rows, 1);
    require(get(standalone_packs) == 3 && get(group_packs) == 0, "three separate packs witness");
    require(get(standalone_integer_rows) == 178 && get(standalone_float_rows) == 0, "standalone rows witness");
    // Fail in the last block after partial packing, then reuse the same backend.
    x.back() = std::numeric_limits<float>::quiet_NaN();
    reset();
    cpu.matmul_group({a.projection(a.group), b.projection(b.group), c.projection(c.group)}, x.data(), width, 1);
    require(get(group_packs) == 0 && get(group_integer_rows) == 0 && get(group_float_rows) == 178, "failed packing fallback witness");
    x.back() = 1;
    reset();
    cpu.matmul_group({a.projection(a.group), b.projection(b.group), c.projection(c.group)}, x.data(), width, 1);
    require(get(group_packs) == 1 && get(group_integer_rows) == 178 && get(group_float_rows) == 0, "packing reuse witness");
    Matrix f(gguf::GGML_TYPE_F32, 64, width, 1, 0);
    Matrix q(gguf::GGML_TYPE_Q4_K, 65, width, 1, 0);
    reset();
    cpu.matmul_group({a.projection(a.group), f.projection(f.group), q.projection(q.group)}, x.data(), width, 1);
    require(get(group_packs) == 1 && get(group_integer_rows) == 49 && get(standalone_packs) == 0, "mixed Q8-only activation witness");
    reset();
    cpu.matmul_group({f.projection(f.group), q.projection(q.group)}, x.data(), width, 1);
    for (int i = 0; i < count; ++i) require(counters[i].load() == 0, "no-Q8 group witness");
    reset();
    cpu.matmul_group({a.projection(a.group)}, x.data(), width, 1);
    require(get(standalone_packs) == 1 && get(group_packs) == 0 && get(standalone_integer_rows) == 49, "single projection dispatch witness");
    std::cout << "shared-pack/separate-pack/failure/reuse witnesses passed\n";
}
#endif
int main() {
    try {
        std::fesetround(FE_TONEAREST);
        quant::register_builtins();
        backend::CpuBackend cpu;
        control_backend::CpuBackend control;
        require(cpu.avx2_, "Q16 oracle requires AVX2 host; no silent skip");
        cpu.matmul_group({}, nullptr, 0, 1);
        unseeded_reuse(cpu, control);
        finite_half_sweep(cpu);
        for (size_t width : {size_t(32), size_t(96), size_t(256), size_t(1024)}) {
            for (size_t batch : {size_t(0), size_t(1), size_t(2), size_t(3)}) {
                std::vector<float> x(width * std::max(batch, size_t(1)));
                for (size_t i = 0; i < x.size(); ++i) x[i] = float(int((i * 43 + 7) % 271) - 135) / 17.0f;
                for (int nt : {1, 2, 6}) {
                    for (size_t small : {size_t(0), size_t(7), size_t(47), size_t(48), size_t(49)}) {
                        case_group(cpu, control, width, batch, nt, false, small, 64, 65, x, 0x3c00);
                        if (width % 256 == 0) case_group(cpu, control, width, batch, nt, true, small, 64, 65, x, 0x3c00);
                    }
                }
            }
        }
        // Signed weight extremes exercise exact integer product limits and tie rounding.
        for (int signed_weight : {-128, 127}) {
            for (float sign : {-1.0f, 1.0f}) {
                std::vector<float> x(32, sign * 32767.0f);
                x[0] = sign * 0.5f; x[1] = sign * 1.5f; x[2] = sign * 2.5f;
                Pack pack(x, 32);
                Matrix m(gguf::GGML_TYPE_Q8_0, 49, 32, 1, 0x3c00);
                for (size_t row = 0; row < m.rows; ++row)
                    std::fill(m.bytes.begin() + row * 34 + 2, m.bytes.begin() + (row + 1) * 34, uint8_t(signed_weight));
                cpu.matmul(m.type, m.data(), x.data(), m.group.data() + 1, 32, m.rows, 1);
                for (size_t row = 0; row < m.rows; ++row) {
                    float expected = 0;
                    require(scalar_dot(m.data() + row * 34, pack, expected), "extreme scalar path");
                    require(equal(m.group[row + 1], expected), "extreme integer products");
                    ++checked;
                }
            }
        }
        // Finite half extremes, signed zero, nonfinite scale and float-result fallback.
        for (uint16_t scale : {uint16_t(0), uint16_t(0x8000), uint16_t(1), uint16_t(0x8001),
             uint16_t(0x0400), uint16_t(0x3c00), uint16_t(0xbc00), uint16_t(0x7bff), uint16_t(0xfbff),
             uint16_t(0x7c00), uint16_t(0x7e00)}) {
            for (float value : {0.0f, 1.0f, -127.0f, 1.2e-34f, 1e-31f, 1e35f, std::numeric_limits<float>::max()}) {
                std::vector<float> x(256, value);
                case_group(cpu, control, 256, 1, 6, false, 49, 64, 65, x, scale);
            }
        }
        for (float bad : {std::numeric_limits<float>::infinity(), -std::numeric_limits<float>::infinity(),
             std::numeric_limits<float>::quiet_NaN(), std::numeric_limits<float>::denorm_min()}) {
            std::vector<float> x(256, 1);
            if (std::isfinite(bad)) std::fill(x.end() - 32, x.end(), bad); else x.back() = bad;
            case_group(cpu, control, 256, 1, 6, true, 49, 64, 65, x, 0x3c00);
            std::fill(x.begin(), x.end(), 0.125f);
            case_group(cpu, control, 256, 1, 6, true, 49, 64, 65, x, 0x3c00);
        }
        // Software half-conversion path must also match the scalar arithmetic.
        cpu.f16c_ = false;
        case_group(cpu, control, 256, 1, 6, false, 49, 64, 65, std::vector<float>(256, -127), 1);
#ifdef Q16_WITNESS
        witness_dispatch(cpu);
#endif
        std::cout << "outputs_checked=" << checked << " scalar/control comparisons passed\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n'; return 1;
    }
}
